import{_ as n,y as l,a as d,o as i,a2 as s,D as r,g as e,I as t}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Downloadable Product","description":"","frontmatter":{},"headers":[],"relativePath":"product-types/downloadable-product.md","filePath":"product-types/downloadable-product.md","lastUpdated":1789441803000}'),p={name:"product-types/downloadable-product.md"};function h(c,o,g,u,w,f){const a=l("ImagePopup");return i(),d("div",null,[o[0]||(o[0]=s('<h1 id="downloadable-product" tabindex="-1">Downloadable Product <a class="header-anchor" href="#downloadable-product" aria-label="Permalink to &quot;Downloadable Product&quot;">​</a></h1><p>A downloadable product is a digital file shoppers download after buying it, such as an e-book, a video course, music or software. You add the files as <strong>links</strong>, each with its own price and download limit, and you can offer free <strong>samples</strong> so shoppers can try before they buy.</p><p>This page covers what&#39;s specific to downloadable products. For the sections every product shares, see <a href="./products.html">Products</a>.</p><h2 id="create-a-downloadable-product" tabindex="-1">Create a downloadable product <a class="header-anchor" href="#create-a-downloadable-product" aria-label="Permalink to &quot;Create a downloadable product&quot;">​</a></h2><p>Create the product as described in <a href="./products.html#create-a-product">Create a product</a>, choosing <strong>Downloadable</strong> as the <strong>Type</strong>.</p><h2 id="how-it-differs-from-other-products" tabindex="-1">How it differs from other products <a class="header-anchor" href="#how-it-differs-from-other-products" aria-label="Permalink to &quot;How it differs from other products&quot;">​</a></h2><ul><li><strong>No Shipping, Inventories or RMA section:</strong> there&#39;s nothing to ship, count or return.</li><li><strong>No Guest Checkout switch:</strong> shoppers must sign in to check out when their cart holds a downloadable product, so their files can be kept in their account.</li><li><strong>Price:</strong> shoppers pay the product&#39;s <strong>Price</strong> plus the price of each link they choose.</li></ul><h2 id="add-download-links" tabindex="-1">Add download links <a class="header-anchor" href="#add-download-links" aria-label="Permalink to &quot;Add download links&quot;">​</a></h2><p>The <strong>Downloadable Links</strong> section lists the files shoppers can buy.</p><ol><li>In <strong>Downloadable Links</strong>, click <strong>Add Link</strong>. The <strong>Link</strong> panel opens.</li><li>Enter the <strong>Title</strong> shoppers see.</li><li>Enter the <strong>Price</strong> added to the product price when a shopper chooses this link. Enter <code>0</code> for no extra charge.</li><li>Enter <strong>Download Allowed</strong>, the number of times a shopper can download the file for each one they buy.</li><li>Choose the <strong>File Type</strong>: <strong>File</strong> to upload the file, or <strong>URL</strong> to link to a file stored elsewhere.</li><li>Upload the <strong>File</strong>, or enter the <strong>URL</strong>.</li><li>To offer a free preview of this link, choose the <strong>Sample Type</strong>.</li><li>Upload the <strong>Sample</strong>, or enter its <strong>URL</strong>.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol>',10)),r(a,{src:"/images/downloadable-product/link-form.png",alt:"Link panel with Title, Price, Download Allowed, File Type and sample fields"}),o[1]||(o[1]=s('<p>Link titles are saved for the language selected at the top of the edit screen. Drag a link by its handle to reorder it, or use <strong>Edit</strong> and <strong>Delete</strong> on its row.</p><h2 id="add-samples" tabindex="-1">Add samples <a class="header-anchor" href="#add-samples" aria-label="Permalink to &quot;Add samples&quot;">​</a></h2><p>Samples in the <strong>Downloadable Samples</strong> section are free files anyone can download from the product page, such as a first chapter.</p><ol><li>In <strong>Downloadable Samples</strong>, click <strong>Add Sample</strong>. A panel titled <strong>Link</strong> opens.</li><li>Enter the <strong>Title</strong>.</li><li>Choose the <strong>File Type</strong>: <strong>File</strong> or <strong>URL</strong>.</li><li>Upload the <strong>File</strong>, or enter the <strong>URL</strong>.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol>',4)),r(a,{src:"/images/downloadable-product/sample-form.png",alt:"Panel for adding a sample, titled Link, with Title, File Type and file fields"}),r(a,{src:"/images/downloadable-product/downloadable-links-samples.png",alt:"Downloadable Links and Downloadable Samples sections with two links and two samples"}),o[2]||(o[2]=e("h2",{id:"what-shoppers-see",tabindex:"-1"},[t("What shoppers see "),e("a",{class:"header-anchor",href:"#what-shoppers-see","aria-label":'Permalink to "What shoppers see"'},"​")],-1)),o[3]||(o[3]=e("p",null,[t("The product page lists the "),e("strong",null,"Samples"),t(" anyone can download, and the "),e("strong",null,"Links"),t(" to buy, each with its price and, when it has one, a "),e("strong",null,"Sample"),t(". Shoppers must tick at least one link before they can add the product to the cart.")],-1)),r(a,{src:"/images/downloadable-product/output.png",alt:"Downloadable product page with Samples and Links"}),o[4]||(o[4]=e("p",null,[t("After the order is invoiced, shoppers download their files from "),e("strong",null,"Downloadable Products"),t(" in their account, which also shows how many downloads they have left. See "),e("a",{href:"./../customer/customer-account.html"},"Customer Account"),t(".")],-1))])}const k=n(p,[["render",h]]);export{b as __pageData,k as default};
